export type CampusPlace = {id:string;site_id:string;building_id:string|null;floor_id:string|null;code:string;name_zh:string;name_en:string;place_type:string;room:string|null;status:string;wheelchair_accessible:boolean|null;verified_at:string;official_source_id:string};
